/*
 * Stands in for `react-native-worklets/src/index.ts`: the module Worklets' native side
 * boots through the reserved module id `-2` (`kWorkletsEntryPointId_` in ScriptLoader.h).
 *
 * The shape is what matters:
 * - it is `WORKLETS_ENTRY_PATHS[0]`, so it is the module that owns `-2`;
 * - the real file assigns `false` to `_WORKLETS_BUNDLE_MODE_ENABLED` and the Worklets
 *   Babel plugin rewrites that literal to `true`, so the literal is kept as-is.
 */

globalThis.__WORKLETS_ENTRY_EVALUATED__ =
  (globalThis.__WORKLETS_ENTRY_EVALUATED__ || 0) + 1;

globalThis._WORKLETS_BUNDLE_MODE_ENABLED = false;

// The real entry exports these. A name like this also satisfies the keyword gate
// `ReanimatedPlugin`'s loader applies, which keeps the file in scope for its rule.
export function runOnUI(fn) {
  return fn;
}

export const __FIXTURE__ = 'react-native-worklets-src-entry';
